using System;using IdleIntelligence.Core;using UnityEngine;using UnityEngine.UI;
namespace IdleIntelligence.Runtime {
 // Non-modal tutorial dock: only its speech bubble receives raycasts. The game and navigation stay usable.
 public sealed class MiraCoach:MonoBehaviour {
  public Image Portrait;public Text Speaker,Speech,Error;public InputField Name;public Button Confirm,Next,Skip,Target;public RectTransform Panel;
  GameState observed;GameRuntime game;string signature,full="";int offset;bool De=>game.State.Settings.language=="de";
  public void Initialize(GameRuntime runtime){game=runtime;Confirm.onClick.AddListener(()=>{var check=NameRules.Validate(Name.text,NameBalance.AIMaximum);if(!check.Ok){Error.gameObject.SetActive(true);Error.text=De?"Bitte einen gültigen Namen wählen.":"Please choose a valid name.";return;}Act("name",Name.text);});Next.onClick.AddListener(()=>{if(offset<full.Length){Page();return;}Act("continue");});Skip.onClick.AddListener(()=>Act(game.State.Story.open==null?"skip-tutorial":"skip"));Target.onClick.AddListener(()=>{var q=TutorialNavigation.Quote(game.State);if(q!=null)game.NavigateTo(q.Tab,q.Element,q.Mode);});foreach(var text in GetComponentsInChildren<Text>(true))if(text.GetComponent<UiLocalizedText>()==null)text.gameObject.AddComponent<UiLocalizedText>().Initialize(game);Refresh();}
  void Act(string op,string value=""){game.Act(s=>NarrativeBridge.Action(s,op,value));signature=null;Refresh();}
  void Update(){if(game!=null)Refresh();}
  void Page(){int end=Math.Min(full.Length,offset+180);if(end<full.Length){int split=full.LastIndexOf(' ',end,end-offset);if(split>offset)end=split;}Speech.text=full.Substring(offset,end-offset).Trim();offset=end;while(offset<full.Length&&full[offset]==' ')offset++;Next.GetComponentInChildren<Text>().text=De?"Weiter":"Continue";}
  void Refresh(){var s=game.State;if(ReferenceEquals(observed,s))return;observed=s;string key=s.Story.open+"|"+s.Story.target+"|"+s.Story.tutorial+"|"+s.Settings.language+"|"+s.Retention.aiName;if(key==signature)return;signature=key;bool naming=string.IsNullOrEmpty(s.Retention.aiName),dialog=s.Story.open!=null;Speaker.text="Dr. Mira Voss";Name.gameObject.SetActive(naming);Confirm.gameObject.SetActive(naming);Next.gameObject.SetActive(!naming&&dialog);Skip.gameObject.SetActive(true);Target.gameObject.SetActive(!naming&&!dialog);Error.text="";Error.gameObject.SetActive(false);Confirm.GetComponentInChildren<Text>().text=De?"Namen bestätigen":"Confirm name";Skip.GetComponentInChildren<Text>().text=De?"Überspringen":"Skip";Target.GetComponentInChildren<Text>().text=De?"Ziel zeigen":"Show target";full=naming?(De?"Willkommen im Labor. Wie soll deine KI heißen?":"Welcome to the laboratory. What should your AI be called?"):dialog?NarrativeBridge.Text(s,s.Story.open):(TutorialNavigation.Quote(s)?.Explanation??"");offset=0;Page();Panel.sizeDelta=new Vector2(-16,naming?266:dialog?240:174);}
 }
}
